import { build } from 'esbuild';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
// The upstream browser distribution declares global HME; it is not an ES/CommonJS module.
const encoder = (
  await readFile(
    `${root}/node_modules/h264-mp4-encoder/embuild/dist/h264-mp4-encoder.web.js`,
    'utf8',
  )
).replace(/\/\/# sourceMappingURL=.*$/m, '');
const license = await readFile(`${root}/node_modules/h264-mp4-encoder/LICENSE.md`, 'utf8');
const { outputFiles } = await build({
  absWorkingDir: root,
  entryPoints: ['src/video/renderer.ts'],
  bundle: true,
  format: 'iife',
  globalName: 'BeforeVideo',
  platform: 'browser',
  target: 'safari16.4',
  minify: true,
  write: false,
  legalComments: 'inline',
});
await mkdir(`${root}/src/video/generated`, { recursive: true });
await writeFile(
  `${root}/src/video/generated/renderer.ts`,
  `// Generated by npm run build:video. Do not edit.\nexport const rendererSource = ${JSON.stringify(`/* ${license} */\n${encoder}\n${outputFiles[0].text}`)};\n`,
);
console.log('Built the offline video renderer.');
